  FacetResult collectTopChildren(StringValueFacetCounts counts, int topN) throws IOException {
    Objects.requireNonNull(reader);
    topN = Math.min(topN, counts.cardinality);
    TopOrdAndIntQueue q = null;
    TopOrdAndIntQueue.OrdAndInt reuse = null;
    int bottomCount = 0;
    int bottomOrd = Integer.MAX_VALUE;
    int childCount = 0; // total number of labels with non-zero count

    if (counts.sparseCounts != null) {
      for (IntIntHashMap.IntIntCursor sparseCount : counts.sparseCounts) {
        childCount++; // every count in sparseValues should be non-zero
        int ord = sparseCount.key;
        int count = sparseCount.value;
        if (count > bottomCount || (count == bottomCount && ord < bottomOrd)) {
          if (q == null) {
            // Lazy init for sparse case:
            q = new TopOrdAndIntQueue(topN);
          }
          if (reuse == null) {
            reuse = (TopOrdAndIntQueue.OrdAndInt) q.newOrdAndValue();
          }
          reuse.ord = ord;
          reuse.value = count;
          reuse = (TopOrdAndIntQueue.OrdAndInt) q.insertWithOverflow(reuse);
          if (q.size() == topN) {
            bottomCount = ((TopOrdAndIntQueue.OrdAndInt) q.top()).value;
            bottomOrd = q.top().ord;
          }
        }
      }
    } else {
      for (int i = 0; i < counts.denseCounts.length; i++) {
        int count = counts.denseCounts[i];
        if (count != 0) {
          childCount++;
          if (count > bottomCount || (count == bottomCount && i < bottomOrd)) {
            if (q == null) {
              // Lazy init for sparse case:
              q = new TopOrdAndIntQueue(topN);
            }
            if (reuse == null) {
              reuse = (TopOrdAndIntQueue.OrdAndInt) q.newOrdAndValue();
            }
            reuse.ord = i;
            reuse.value = count;
            reuse = (TopOrdAndIntQueue.OrdAndInt) q.insertWithOverflow(reuse);
            if (q.size() == topN) {
              bottomCount = ((TopOrdAndIntQueue.OrdAndInt) q.top()).value;
              bottomOrd = q.top().ord;
            }
          }
        }
      }
    }

    int resultCount = q == null ? 0 : q.size();
    LabelAndValue[] labelValues = new LabelAndValue[resultCount];
    for (int i = labelValues.length - 1; i >= 0; i--) {
      TopOrdAndIntQueue.OrdAndInt ordAndValue = (TopOrdAndIntQueue.OrdAndInt) q.pop();
      labelValues[i] =
          new LabelAndValue(counts.lookupOrdAsString(ordAndValue.ord), ordAndValue.value);
    }

    return new FacetResult(field, new String[0], counts.totalDocCount, labelValues, childCount);
  }

  @Override
  public String toString() {
    return "StringDocValuesReaderState(field=" + field + " reader=" + reader + ")";
